+    fn start_timing(&self) -> StartTiming {
+        match (self.control >> START_TIMING_SHIFT) & 3 {
+            0 => StartTiming::Immediate,
+            1 => StartTiming::VBlank,
+            2 => StartTiming::HBlank,
+            _ => StartTiming::Special,
